package io.github.jasper.monitoring.api.management.query;
import io.github.jasper.monitoring.api.management.ManagementPageRequest;
public final class SecurityEventQuery extends ManagementQuery { public enum Sort { OCCURRED_AT, RISK, ACTION, ID } private final java.time.Instant from,to; private SecurityEventQuery(ManagementPageRequest p,java.time.Instant from,java.time.Instant to){super(p);if(from==null||to==null||to.isBefore(from)||java.time.Duration.between(from,to).compareTo(java.time.Duration.ofDays(31))>0)throw new IllegalArgumentException("bounded time range required");this.from=from;this.to=to;} public static SecurityEventQuery of(ManagementPageRequest p,java.time.Instant from,java.time.Instant to){return new SecurityEventQuery(p,from,to);} public java.time.Instant getFrom(){return from;} public java.time.Instant getTo(){return to;} }
